-- Starting points for a new skin.
--
-- Every pixel here is generated by this file. The figures are generic humanoid
-- bases drawn to the Minecraft layout -- they are not Mojang's Steve or Alex
-- textures, which are Mojang's assets and are deliberately not redistributed.

local model = require("src.model")
local fetch = require("src.skinfetch")

local M = {}

local SIZE <const> = 64

local function rgba(c) return app.pixelColor.rgba(c[1], c[2], c[3], c[4] or 255) end

local function blank()
  local img = Image(SIZE, SIZE, ColorMode.RGB)
  local clear = app.pixelColor.rgba(0, 0, 0, 0)
  for y = 0, SIZE - 1 do
    for x = 0, SIZE - 1 do img:drawPixel(x, y, clear) end
  end
  return img
end

-- ------------------------------------------------------------- base figure --

local PALETTES <const> = {
  classic = {
    skin  = { 198, 150, 110 }, hair     = {  74,  49,  32 },
    shirt = {  62, 110, 170 }, trousers = {  58,  66, 110 },
    shoe  = {  68,  68,  78 }, eye      = { 234, 234, 238 },
    iris  = {  70,  90, 160 }, mouth    = { 120,  84,  64 },
  },
  slim = {
    skin  = { 214, 164, 120 }, hair     = { 198, 112,  46 },
    shirt = {  92, 150,  92 }, trousers = { 112,  82,  56 },
    shoe  = {  68,  68,  78 }, eye      = { 234, 234, 238 },
    iris  = {  92, 140,  92 }, mouth    = { 132,  92,  70 },
  },
}

-- Which color a texel takes, given where it sits on its face. `dy` counts
-- down from the top of the face, so "hair on the top three rows" and "hands on
-- the bottom four" are expressed directly.
local function figurePixel(part, face, dx, dy, w, h, pal)
  if part == "head" then
    if face == "top"    then return pal.hair end
    if face == "bottom" then return pal.skin end
    if dy < 3 then return pal.hair end
    if face == "front" then
      if dy == 4 then
        if dx == 1 or dx == 6 then return pal.eye  end
        if dx == 2 or dx == 5 then return pal.iris end
      end
      if dy == 6 and dx >= 2 and dx <= 5 then return pal.mouth end
    end
    return pal.skin

  elseif part == "body" then
    if face == "bottom" then return pal.trousers end
    return pal.shirt

  elseif part == "rightArm" or part == "leftArm" then
    if face == "top"    then return pal.shirt end
    if face == "bottom" then return pal.skin  end
    return (dy >= 8) and pal.skin or pal.shirt   -- sleeve, then bare hand

  else -- legs
    if face == "top"    then return pal.trousers end
    if face == "bottom" then return pal.shoe     end
    return (dy >= 9) and pal.shoe or pal.trousers
  end
end

-- -------------------------------------------------------------- UV guide --

local GUIDE <const> = {
  head     = { 226,  92,  92 }, body     = {  92, 190, 112 },
  rightArm = {  92, 140, 232 }, leftArm  = { 232, 198,  84 },
  rightLeg = { 198, 112, 216 }, leftLeg  = {  92, 202, 202 },
}

local function mix(c, other, t)
  return { math.floor(c[1] + (other[1] - c[1]) * t),
           math.floor(c[2] + (other[2] - c[2]) * t),
           math.floor(c[3] + (other[3] - c[3]) * t) }
end

local WHITE <const> = { 255, 255, 255 }
local BLACK <const> = { 0, 0, 0 }

--- Guide texel: the part's hue, lightened for the outer layer, with a darker
-- one-pixel border so every face rect's boundary is visible while painting.
local function guidePixel(part, layer, dx, dy, w, h)
  local base = GUIDE[part]
  local c = (layer == "overlay") and mix(base, WHITE, 0.45) or base
  local edge = (dx == 0 or dy == 0 or dx == w - 1 or dy == h - 1)
  if edge then return mix(c, BLACK, 0.35) end
  return c
end

-- ------------------------------------------------------------------- API --

--- Paint every face of the model through `pixelFn(part, layer, face, dx, dy, w, h)`.
-- Returning nil leaves the texel transparent.
local function paint(slim, layers, pixelFn)
  local img = blank()
  for _, f in ipairs(model.build(slim)) do
    if layers[f.layer] then
      local u, v, w, h = f.uv[1], f.uv[2], f.uv[3], f.uv[4]
      for dy = 0, h - 1 do
        for dx = 0, w - 1 do
          local c = pixelFn(f.part, f.layer, f.name, dx, dy, w, h)
          if c then img:drawPixel(u + dx, v + dy, rgba(c)) end
        end
      end
    end
  end
  return img
end

--- Build a 64x64 template image. `slim` picks the three-wide arm layout, which
-- changes the arm UV rects and so must be baked into the pixels.
function M.build(id, slim)
  if id == "figure" then
    local pal = PALETTES[slim and "slim" or "classic"]
    return paint(slim, { base = true }, function(part, layer, face, dx, dy, w, h)
      return figurePixel(part, face, dx, dy, w, h, pal)
    end)
  elseif id == "guide" then
    return paint(slim, { base = true, overlay = true }, guidePixel)
  end
  return blank()
end

--- Palette made of the colors actually used in `img`, grouped by hue and
-- then by brightness so related shades sit together. A sprite created from a
-- script otherwise starts with an all-black palette, which is useless for
-- picking the skin's own colors back up.
local function paletteFor(img)
  local pc = app.pixelColor
  local seen, colors = {}, {}
  for y = 0, img.height - 1 do
    for x = 0, img.width - 1 do
      local px = img:getPixel(x, y)
      if pc.rgbaA(px) > 0 and not seen[px] then
        seen[px] = true
        colors[#colors + 1] = Color{ r = pc.rgbaR(px), g = pc.rgbaG(px),
                                     b = pc.rgbaB(px), a = pc.rgbaA(px) }
      end
    end
  end
  -- Nothing painted yet (the blank template): Aseprite's own default palette
  -- is a far better starting point than a single transparent entry.
  if #colors == 0 then
    local ok, pal = pcall(function() return Palette(app.defaultPalette) end)
    return ok and pal or nil
  end

  local function key(c)
    -- Grays have no meaningful hue; keep them together at the front.
    local gray = c.hsvSaturation < 0.08
    return gray and -1 or (c.hsvHue // 30), c.hsvValue
  end
  table.sort(colors, function(a, b)
    local ha, va = key(a)
    local hb, vb = key(b)
    if ha ~= hb then return ha < hb end
    if va ~= vb then return va < vb end
    return a.rgbaPixel < b.rgbaPixel
  end)

  -- Entry 0 stays transparent, as Aseprite expects of an RGB sprite's palette.
  local n = math.min(#colors, 255)
  local pal = Palette(n + 1)
  pal:setColor(0, Color{ r = 0, g = 0, b = 0, a = 0 })
  for i = 1, n do pal:setColor(i, colors[i]) end
  return pal
end

--- Wrap a 64x64 image as a new skin sprite, with a palette of its colors.
local function spriteFromImage(img)
  local spr = Sprite(SIZE, SIZE, ColorMode.RGB)
  spr:newCel(spr.layers[1], 1, img, Point(0, 0))
  spr.layers[1].name = "Skin"
  local pal = paletteFor(img)
  if pal then spr:setPalette(pal) end
  return spr
end

--- Create the sprite and place the template on its first cel.
function M.newSprite(id, slim)
  return spriteFromImage(M.build(id, slim))
end

-- What the chooser offers, in display order. "default" is Mojang's own skin
-- for the chosen model -- Steve for classic, Alex for slim -- so the two can
-- never disagree and the list stays the same length whichever model is picked.
local CHOICES <const> = {
  { id = "default", text = "Default" },
  { id = "guide",   text = "UV guide" },
  { id = "blank",   text = "Blank" },
}
local MODELS <const> = {
  { id = "classic", text = "Classic", fetchId = "steve" },
  { id = "slim",    text = "Slim",    fetchId = "alex" },
}

--- Small modal chooser. Returns the new Sprite, or nil if canceled.
function M.chooser()
  local created
  local modelIndex, choiceIndex = 1, 1

  local dlg = Dialog("New Minecraft Skin")

  -- One row of radio buttons per choice. A click re-asserts both rows from
  -- our own indices rather than trusting Aseprite's implicit grouping, so one
  -- row can never knock out the selection in the other.
  local rows = {
    { prefix = "model_", label = "Model",      entries = MODELS,
      get = function() return modelIndex end,  set = function(i) modelIndex = i end },
    { prefix = "from_",  label = "Start from", entries = CHOICES,
      get = function() return choiceIndex end, set = function(i) choiceIndex = i end },
  }
  local function syncRadios()
    for _, row in ipairs(rows) do
      for i, e in ipairs(row.entries) do
        dlg:modify{ id = row.prefix .. e.id, selected = (i == row.get()) }
      end
    end
  end
  for _, row in ipairs(rows) do
    for i, e in ipairs(row.entries) do
      dlg:radio{
        id = row.prefix .. e.id,
        label = (i == 1) and row.label or nil,
        text = e.text,
        selected = (i == row.get()),
        onclick = function()
          row.set(i)
          syncRadios()
        end,
      }
    end
  end

  --- Mojang's skin for the model from the cache, or -- when it is not there --
  -- our own rough stand-in figure, so "Default" always produces something to
  -- paint on. `err` is why the download just failed, if one was attempted.
  local function createDefault(mdl, err)
    local img = fetch.cached(mdl.fetchId)
    if img then
      created = spriteFromImage(img)
      return
    end
    app.alert{ title = "New Minecraft Skin",
               text = { "The default skin could not be downloaded:",
                        tostring(err or "it was not found after the download."),
                        "Starting from a rough placeholder figure instead." } }
    created = M.newSprite("figure", mdl.id == "slim")
  end

  local pending
  dlg:button{
    id = "ok", text = "Create", focus = true,
    onclick = function()
      if pending then return end
      local mdl = MODELS[modelIndex]
      local choice = CHOICES[choiceIndex]
      if choice.id ~= "default" then
        created = M.newSprite(choice.id, mdl.id == "slim")
        dlg:close()
      elseif fetch.isCached(mdl.fetchId) then
        createDefault(mdl)
        dlg:close()
      else
        -- First use: say what is about to happen before Aseprite's own
        -- permission question appears, so that question is not a surprise.
        local answer = app.alert{
          title = "Download default skins",
          text = { "The Steve and Alex skins need to be downloaded from Mojang. This will only happen once.",
                   "Aseprite will ask for permission next. Choose Allow Execute Access to continue." },
          buttons = { "Download", "Cancel" },
        }
        if answer ~= 1 then return end

        -- The download blocks the UI while curl runs, so say what is happening
        -- first and start it from a timer: that gives the button one paint
        -- before everything freezes.
        dlg:modify{ id = "ok", text = "Downloading...", enabled = false }
        pending = Timer{ interval = 0.1, ontick = function()
          pending:stop()
          pending = nil
          local _, err = fetch.downloadAll()
          createDefault(mdl, err)
          dlg:close()
        end }
        pending:start()
      end
    end,
  }
  dlg:button{ id = "cancel", text = "Cancel", onclick = function() dlg:close() end }
  dlg:show()
  if pending then pending:stop() end
  return created
end

return M
